const equipmentCategories=['Control','Engines','Weapons','Armor','Shields','Colony','Storage','Supplies','Scanners','Shipyards','Hangars','Mining','Stellar','Other'];
function partCategory(c){if(c.supplies)return 'Supplies';return ({'Vehicle Control':'Control','Engines':'Engines','Weapons':'Weapons','Armor':'Armor','Shields':'Shields','Colonizing':'Colony','Cargo':'Storage','Supply':'Supplies','Sensors':'Scanners','Construction':'Shipyards','Unit Launch':'Hangars','Remote Mining':'Mining','Stellar Manipulation':'Stellar'})[c.group]||'Other';}
