function requiredPart(c){const hull=current.catalog.hulls.find(h=>h.id===draft.hull);return partCategory(c)==='Control'||(hull?.requiredColony&&c.colonyModule)||(hull?.requiredCargo&&c.cargoStorage)||(hull?.requiredFighters&&c.fighterBay);}
