 const coreProblems=stats.problems.filter(p=>/bridge|life support|crew quarters|cockpit|computer core|auxiliary control|colony modules|cargo space|fighter bays/i.test(p));
 const next=$('#design-next');if(next){const blocked=!draft.design_type.trim()||(designerStep===1&&coreProblems.length>0);next.dataset.unavailable=String(blocked);next.disabled=processing||blocked;}
 for(const add of document.querySelectorAll('.component-add,.component-increment')){const c=current.catalog.components.find(c=>c.id===Number(add.dataset.component));const check=stats.additions.find(a=>a.id===c.id);const tooLarge=stats.used+c.tonnage>stats.capacity;const blocked=tooLarge||check?.allowed===false;add.dataset.unavailable=String(blocked);add.disabled=processing||blocked;add.title=blocked?(check?.reason||'Not enough space'):'';if(add.classList.contains('component-add'))add.textContent=blocked?(tooLarge?'No room':/^At most|only one/i.test(check?.reason||'')?'Limit':'Fitted'):'Add';}

 const issues=$('#design-issues');if(issues){issues.replaceChildren();for(const problem of stats.problems)issues.append(node('li','',problem));if(!stats.problems.length)issues.append(node('li','design-valid','Ready to save'));}
